namespace $.$$ {

	/**
	 * Properties of whatever is selected, in the panel on the right.
	 *
	 * Every field is a two-way binding straight onto the store, and the store
	 * writes straight into the Baza. There is no draft state and no Apply button
	 * on purpose: an inspector produces a handful of writes per minute, unlike a
	 * drag, so buffering them would only add a way for the panel and the canvas
	 * to disagree.
	 *
	 * Which rows show up depends on the kind of the node, and the rows themselves
	 * are ordinary named sub-views rather than a keyed factory — there is a fixed,
	 * small set of them, and naming each one keeps the bindings readable.
	 *
	 * Several elements at once get a count and the delete button, and nothing
	 * else: a width typed into a field would be the width of every one of them,
	 * which is a decision of its own rather than a row that happens to work.
	 */
	export class $bog_figmol_app_inspector extends $.$bog_figmol_app_inspector {

		kind() {
			return this.store().kind( this.selected() )
		}

		many() {
			return this.selection().length > 1
		}

		kind_title() {

			if( this.many() ) return this.title_many() + ': ' + this.selection().length

			switch( this.kind() ) {
				case 'text': return this.title_text()
				case 'image': return this.title_image()
				case 'button': return this.title_button()
				case 'frame': return this.title_frame()
				case 'rect': return this.title_rect()
				// An instance is named after what it draws — the kind of every one
				// of them is the same word, and the component is the useful half.
				case 'inst': return this.comp_title() || $bog_figmol_blocks.title( 'inst' )
				default: return $bog_figmol_blocks.title( this.kind() )
			}
		}

		drop_caption() {
			return this.many() ? this.drop_many_label() : this.drop_label()
		}

		@ $mol_mem
		rows(): readonly $mol_view[] {

			const id = this.selected()
			if( !id ) return []

			if( this.many() ) {
				const res = [ this.Head() ] as $mol_view[]
				if( this.arrangeable() ) res.push( this.Arrange() )
				res.push( this.Drop() )
				return res
			}

			const kind = this.kind()
			const res = [ this.Head() ] as $mol_view[]

			// Coordinates of a node inside an auto layout would be a lie: the frame
			// places it, and typing into X there changes nothing anybody can see.
			if( !this.store().flow( id ) ) res.push( this.Field_x(), this.Field_y() )

			res.push( this.Field_w(), this.Field_h() )

			if( this.store().container( id ) ) res.push(
				this.Field_direction(),
				this.Field_gap(),
				this.Field_padding(),
				this.Field_align(),
			)

			res.push( ... this.kind_rows( kind ) )

			if( this.makeable() ) res.push( this.Comp_make() )

			res.push( this.Drop() )

			return res
		}

		/* ----------------------------------------------------------- components */

		/**
		 * Whether this element can become a component. The root frame cannot: it
		 * is the page, and a page that is an instance of something has nowhere to
		 * put the instance. An instance cannot either — it is one already.
		 */
		makeable() {
			const id = this.selected()
			const store = this.store()
			return !!id && !!store.parent( id ) && store.kind( id ) !== 'inst'
		}

		comp_title() {
			const store = this.store()
			return store.comp_title( store.master( this.selected() ) )
		}

		/**
		 * Turns the selected element into a component and picks the instance that
		 * took its place. One gesture, so one step back: the master moves, the
		 * node is unlinked and an instance is written, and Ctrl+Z undoes the lot.
		 */
		@ $mol_action
		comp_make( next?: any ) {

			if( next === undefined ) return null

			const store = this.store()
			const id = this.selected()
			if( !id ) return null

			const title = store.text( id ).replace( /\s+/g, ' ' ).trim()
				|| $bog_figmol_blocks.title( store.kind( id ) )

			let made = ''
			store.group( ()=> { made = store.comp_make( id, title ) } )

			if( made ) this.selected( made )

			return null
		}

		/**
		 * Opens the master of this instance. The selection goes with it: the node
		 * it names belongs to the page, which the canvas is about to leave.
		 */
		@ $mol_action
		comp_edit( next?: any ) {

			if( next === undefined ) return null

			const store = this.store()
			const comp = store.master( this.selected() )
			if( !comp ) return null

			store.comp_id( comp )
			this.selected( '' )

			return null
		}

		/* ------------------------------------------------------------ arranging */

		/**
		 * Whether there is anything to line up: two elements at least, and every
		 * one of them placed by its own coordinates. Inside an auto layout the
		 * frame decides where things go, and a button that fought it would only
		 * write numbers nobody would see.
		 */
		arrangeable() {
			const store = this.store()
			return this.selection().filter( id => !store.flow( id ) ).length > 1
		}

		align_left( next?: any ) {
			return this.align_ask( 'left', next )
		}

		align_hcenter( next?: any ) {
			return this.align_ask( 'hcenter', next )
		}

		align_right( next?: any ) {
			return this.align_ask( 'right', next )
		}

		align_hspace( next?: any ) {
			return this.align_ask( 'hspace', next )
		}

		align_top( next?: any ) {
			return this.align_ask( 'top', next )
		}

		align_vcenter( next?: any ) {
			return this.align_ask( 'vcenter', next )
		}

		align_bottom( next?: any ) {
			return this.align_ask( 'bottom', next )
		}

		align_vspace( next?: any ) {
			return this.align_ask( 'vspace', next )
		}

		/**
		 * Hands the mode over to the app, which is where the canvas is and hence
		 * where the elements can be measured. The panel knows what was asked for
		 * and nothing about where anything sits.
		 */
		align_ask( mode: string, next?: any ) {
			if( next === undefined ) return null
			this.arrange( mode )
			return null
		}

		/** Rows that only one kind of element has any use for. */
		kind_rows( kind: string ): readonly $mol_view[] {
			switch( kind ) {
				case 'text': return [
					this.Field_text(),
					this.Field_size(),
					this.Field_weight(),
					this.Field_text_align(),
					this.Field_color(),
				]
				case 'button': return [ this.Field_label(), this.Field_uri(), this.Field_color(), this.Field_back() ]
				case 'image': return [ this.Field_uri() ]
				case 'rect': return [ this.Field_back() ]
				case 'frame': return [ this.Field_back() ]
				case 'bui_button': return [ this.Field_label(), this.Field_variant() ]
				case 'bui_badge': return [ this.Field_label(), this.Field_tone() ]
				case 'bui_alert': return [ this.Field_label(), this.Field_note() ]
				case 'bui_field': return [ this.Field_hint() ]
				case 'bui_progress': return [ this.Field_value(), this.Field_max() ]
				case 'bui_tabs': return [ this.Field_options() ]
				case 'bui_avatar': return [ this.Field_uri() ]
				case 'inst': return [ this.Field_comp(), this.Comp_edit() ]
			}
			return []
		}

		x( next?: number ) {
			return this.store().x( this.selected(), next )
		}

		y( next?: number ) {
			return this.store().y( this.selected(), next )
		}

		w( next?: number ) {
			return this.store().w( this.selected(), next )
		}

		h( next?: number ) {
			return this.store().h( this.selected(), next )
		}

		/**
		 * A frame without a direction places its kids by hand. The switch spells
		 * that out as `free` rather than as an empty option — an unlabelled button
		 * next to Row and Column reads like a bug.
		 */
		direction( next?: string ) {
			const store = this.store()
			const id = this.selected()
			if( next !== undefined ) store.direction( id, next === 'free' ? '' : next )
			return store.direction( id ) || 'free'
		}

		gap( next?: number ) {
			return this.store().gap( this.selected(), next )
		}

		padding( next?: number ) {
			return this.store().padding( this.selected(), next )
		}

		align( next?: string ) {
			return this.store().align( this.selected(), next )
		}

		text( next?: string ) {
			return this.store().text( this.selected(), next )
		}

		note( next?: string ) {
			return this.store().note( this.selected(), next )
		}

		uri( next?: string ) {
			return this.store().uri( this.selected(), next )
		}

		variant( next?: string ) {
			return this.store().variant( this.selected(), next )
		}

		options( next?: string ) {
			return this.store().options( this.selected(), next )
		}

		color( next?: string ) {
			return this.store().color( this.selected(), next )
		}

		back( next?: string ) {
			return this.store().back( this.selected(), next )
		}

		weight( next?: string ) {
			return this.store().weight( this.selected(), next )
		}

		text_align( next?: string ) {
			return this.store().text_align( this.selected(), next )
		}

		font_size( next?: number ) {
			return this.store().font_size( this.selected(), next )
		}

		progress( next?: number ) {
			return this.store().progress( this.selected(), next )
		}

		progress_max( next?: number ) {
			return this.store().progress_max( this.selected(), next )
		}

		@ $mol_action
		node_drop( next?: any ) {

			if( next === undefined ) return null

			const ids = this.selection()
			if( !ids.length ) return null

			const store = this.store()
			store.group( ()=> { for( const id of ids ) store.node_drop( id ) } )

			this.selected( '' )

			return null
		}

	}

}
